package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;

/**
 * Responds 400 with an RFC7807 {@code application/problem+json} body when the create-owner
 * telephone cannot be converted to a valid E.164 number.
 */
public class OwnerTelephoneInvalidExceptionHandler {

    public void handle(@Parameter OwnerTelephoneInvalidException ex,
